-- -----------------------------------------------------------------------------
-- Guards
-- -----------------------------------------------------------------------------
DO $$
DECLARE n int; bad int;
BEGIN
  -- 🔑 EVERY GUARD IS SCOPED TO THIS COHORT. Season 2 already held 36 rows on these two topics
  -- for OTHER politicians (4 zoning, 32 transportation, written 2026-09-08..11). A topic-wide
  -- count would fold them in and assert the wrong number -- the first draft of this guard did.

  -- every member got exactly one Transportation row and one blanked zoning row
  SELECT count(*) INTO n FROM inform.politician_answers
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='ba59337e-30e2-4aba-a39a-426b3366eb27' AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF n <> 82 THEN
    RAISE EXCEPTION 'migration 1882: expected 82 Season 2 Transportation answers for the cohort, found %', n;
  END IF;

  SELECT count(*) INTO n FROM inform.politician_answers
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND value=0 AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF n <> 82 THEN
    RAISE EXCEPTION 'migration 1882: expected 82 blanked Season 2 zoning answers for the cohort, found %', n;
  END IF;

  -- the grading split must be exactly what the header argues
  SELECT count(*) INTO n FROM inform.politician_answers
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='ba59337e-30e2-4aba-a39a-426b3366eb27' AND value=1 AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF n <> 51 THEN
    RAISE EXCEPTION 'migration 1882: expected 51 Yea voters at Transportation stance 1, found %', n;
  END IF;
  SELECT count(*) INTO n FROM inform.politician_answers
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='ba59337e-30e2-4aba-a39a-426b3366eb27' AND value=4 AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF n <> 31 THEN
    RAISE EXCEPTION 'migration 1882: expected 31 Nay voters at Transportation stance 4, found %', n;
  END IF;

  -- no chair outside the two this migration argues for
  SELECT count(*) INTO bad FROM inform.politician_answers
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='ba59337e-30e2-4aba-a39a-426b3366eb27' AND value NOT IN (1,4)
     AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF bad <> 0 THEN
    RAISE EXCEPTION 'migration 1882: % cohort Transportation answer(s) outside {1,4}', bad;
  END IF;

  -- every new row carries context, and every context row carries its roll-call source
  SELECT count(*) INTO bad
    FROM inform.politician_answers a
    LEFT JOIN inform.politician_context c
      ON c.politician_id=a.politician_id AND c.topic_id=a.topic_id AND c.season_id=a.season_id
   WHERE a.season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND a.topic_id IN ('d4f18138-a2e0-4110-b925-7387d9d0d16d','ba59337e-30e2-4aba-a39a-426b3366eb27')
     AND a.politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%') AND c.politician_id IS NULL;
  IF bad <> 0 THEN
    RAISE EXCEPTION 'migration 1882: % new answer row(s) have no context row', bad;
  END IF;

  SELECT count(*) INTO bad FROM inform.politician_context
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id IN ('d4f18138-a2e0-4110-b925-7387d9d0d16d','ba59337e-30e2-4aba-a39a-426b3366eb27')
     AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%')
     AND NOT EXISTS (SELECT 1 FROM unnest(sources) s WHERE s ILIKE '%LD=427%' OR s ILIKE '%serialnumber=534%');
  IF bad <> 0 THEN
    RAISE EXCEPTION 'migration 1882: % new context row(s) do not cite the LD 427 roll call', bad;
  END IF;

  -- no re-filed row may repeat the wrong ladder's language
  SELECT count(*) INTO bad FROM inform.politician_context
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id='ba59337e-30e2-4aba-a39a-426b3366eb27' AND politician_id IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%')
     AND (reasoning ILIKE '%upzone%' OR reasoning ILIKE '%multifamily by right%');
  IF bad <> 0 THEN
    RAISE EXCEPTION 'migration 1882: % re-filed Transportation row(s) still carry zoning-ladder language', bad;
  END IF;

  -- the 36 pre-existing Season 2 rows on these topics must be untouched
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id='86d893a1-c1a2-4bbf-b4e5-69ec43221194' AND topic_id IN ('d4f18138-a2e0-4110-b925-7387d9d0d16d','ba59337e-30e2-4aba-a39a-426b3366eb27')
     AND politician_id NOT IN (SELECT politician_id FROM inform.politician_context
                    WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%');
  IF n <> 36 THEN
    RAISE EXCEPTION 'migration 1882: expected the 36 pre-existing non-cohort Season 2 rows to be untouched, found %', n;
  END IF;

  -- 🔴 SEASON 1 MUST BE BYTE-FOR-BYTE INTACT
  SELECT count(*) INTO n FROM inform.politician_context
   WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%';
  IF n <> 82 THEN
    RAISE EXCEPTION 'migration 1882: Season 1 zoning context rows changed -- found %, expected 82', n;
  END IF;
  SELECT count(*) INTO n FROM inform.politician_answers
   WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d'
     AND politician_id IN (SELECT politician_id FROM inform.politician_context
                            WHERE season_id='2d5d67d1-2a2a-4c73-88bb-3c2e3e33cba3' AND topic_id='d4f18138-a2e0-4110-b925-7387d9d0d16d' AND reasoning ILIKE '%LD 427%')
     AND value = 0;
  IF n <> 0 THEN
    RAISE EXCEPTION 'migration 1882: % Season 1 answer(s) were blanked -- history was edited', n;
  END IF;
END $$;

COMMIT;
